def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total_sites = v1 + v2 + v3

    return {
        "value": total_sites,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "total_sites": total_sites,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "communications sites"
            }
        }
    }
